"use client";
import type { components } from "@/lib/api-schema";
import { Calculated, References, minutes } from "./evidence-views";
type Analysis = components["schemas"]["AnalysisOut"];
const shortDate = (value: string) =>
  new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    timeZone: "UTC",
  }).format(new Date(`${value}T12:00:00Z`));

export function AnswerBody({
  result,
  onSource,
}: {
  result: NonNullable<Analysis["result"]>;
  onSource: (revision: string, span: string) => void;
}) {
  const answer = result.answer;
  if (!answer) return null;
  const value = result.calculations;
  const unresolved =
    value?.contributions.filter(
      (row) =>
        row.disposition !== "excluded" &&
        (row.disposition === "uncertain" || row.seconds.length !== 1),
    ) ?? [];
  const sharedGoal = value?.weeks[0];
  const sameGoal =
    sharedGoal &&
    value?.weeks.every(
      (week) =>
        week.minimum_days === sharedGoal.minimum_days &&
        week.minimum_minutes === sharedGoal.minimum_minutes,
    );
  return (
    <>
      <div className="answer-summary">
        {value ? (
          <>
            <p className="answer-lead">
              {value.total.sessions !== null && value.total.days !== null ? (
                <>
                  <strong>
                    {value.total.sessions}{" "}
                    {value.total.sessions === 1 ? "session" : "sessions"}
                  </strong>{" "}
                  across{" "}
                  <strong>
                    {value.total.days} treatment{" "}
                    {value.total.days === 1 ? "day" : "days"}
                  </strong>
                  ,{" "}
                  {value.total.complete ? (
                    <>
                      totaling <strong>{minutes(value.total.seconds)}</strong>.
                    </>
                  ) : (
                    "with treatment time still undetermined."
                  )}
                </>
              ) : (
                "A complete total cannot be determined from the available evidence."
              )}
            </p>
            <p className="answer-scope">
              {value.total.start} – {value.total.end}
            </p>
            {value.weeks.length > 0 && (
              <>
                <p className="answer-goal">
                  {sameGoal
                    ? `Weekly goal: at least ${sharedGoal.minimum_days} days and ${sharedGoal.minimum_minutes} minutes.`
                    : "Weekly treatment goals:"}
                </p>
                <ul className="answer-weeks">
                  {value.weeks.map((week, index) => (
                    <li key={index}>
                      <span>
                        {shortDate(week.start!)} – {shortDate(week.end!)}
                        <small>
                          {week.days ?? "Unknown"} days ·{" "}
                          {minutes(week.seconds)}
                          {!sameGoal &&
                            ` · Goal: ${week.minimum_days} days and ${week.minimum_minutes} min`}
                        </small>
                      </span>
                      <strong className={`disposition ${week.goal_status}`}>
                        {week.goal_status === "met"
                          ? "Met"
                          : week.goal_status === "not_met"
                            ? "Not met"
                            : "Cannot determine"}
                      </strong>
                    </li>
                  ))}
                </ul>
              </>
            )}
            {unresolved.length > 0 && (
              <div className="answer-uncertainty">
                <strong>Why the uncertainty?</strong>
                {unresolved.map((row) => (
                  <p key={row.encounter_id}>
                    {shortDate(row.date)}:{" "}
                    {row.seconds.length > 1 ? (
                      <>
                        conflicting accounts document{" "}
                        <strong>{minutes(row.seconds)}</strong> for the same
                        encounter.
                      </>
                    ) : row.disposition === "uncertain" ? (
                      "attendance or eligibility is uncertain."
                    ) : (
                      "patient-contact duration is unknown."
                    )}
                  </p>
                ))}
              </div>
            )}
            {!value.total.complete && unresolved.length === 0 && (
              <p className="answer-uncertainty">
                Source coverage is incomplete. Review the evidence before using
                these totals.
              </p>
            )}
          </>
        ) : (
          <>
            {answer.statements.slice(0, 3).map((claim, index) => (
              <p className="answer-narrative" key={index}>
                {claim.text}
              </p>
            ))}
            {answer.limitations.slice(0, 2).map((limitation, index) => (
              <p className="answer-uncertainty" key={index}>
                {limitation}
              </p>
            ))}
            {!answer.statements.length && !answer.limitations.length && (
              <p>
                The available records do not support an answer to this question.
              </p>
            )}
          </>
        )}
      </div>
      <details className="answer-evidence">
        <summary>View explanation, sources, and calculation details</summary>
        {answer.statements.map((claim, index) => (
          <div className="finding" key={index}>
            <p>{claim.text}</p>
            <References
              ids={claim.citations}
              citations={result.citations}
              onSource={onSource}
            />
          </div>
        ))}
        {value && (
          <Calculated
            value={value}
            citations={result.citations}
            onSource={onSource}
          />
        )}
        {answer.limitations.length > 0 && (
          <div className="answer-qualifications">
            <h4>Limitations</h4>
            {answer.limitations.map((limitation, index) => (
              <p key={index}>{limitation}</p>
            ))}
          </div>
        )}
      </details>
    </>
  );
}
