"use client";
import type { components } from "@/lib/api-schema";
type Citation = components["schemas"]["CitationOut"];
type Calculations = components["schemas"]["Calculations"];
type Claim = components["schemas"]["Claim"];
export const minutes = (seconds: number[]) =>
  seconds.length
    ? seconds.map((value) => `${value / 60}`).join(" or ") + " min"
    : "Unknown";
export const human = (value: string) =>
  value === "claude_credit_balance_low"
    ? "Anthropic credits are exhausted. Add credits to your Anthropic account, then retry."
    : value === "answer_requires_review"
      ? "The answer did not pass its source check, so it was not published."
      : value === "abstraction_requires_review"
        ? "No source-checked abstraction is ready. Retry the flagged documents."
        : value.replaceAll("_", " ");

export function References({
  ids,
  citations,
  onSource,
}: {
  ids: string[];
  citations: Citation[];
  onSource: (revision: string, span: string) => void;
}) {
  return (
    <div className="evidence-links">
      {[...new Set(ids)].map((id) => {
        const citation = citations.find((value) => value.span_id === id);
        return citation ? (
          <button
            key={id}
            title={citation.quote}
            onClick={() => onSource(citation.revision_id, id)}
          >
            {citation.filename.split("_")[0]} · L{citation.start_line}–
            {citation.end_line} ↗
          </button>
        ) : null;
      })}
    </div>
  );
}

export function Findings({
  claims,
  citations,
  onSource,
}: {
  claims: Claim[];
  citations: Citation[];
  onSource: (revision: string, span: string) => void;
}) {
  return (
    <div className="clinical-findings">
      {claims.map((claim, index) => (
        <article key={index} className="finding">
          <span className="eyebrow">{claim.category}</span>
          <p>{claim.text}</p>
          <References
            ids={claim.citations}
            citations={citations}
            onSource={onSource}
          />
        </article>
      ))}
    </div>
  );
}

export function Calculated({
  value,
  citations,
  onSource,
}: {
  value: Calculations;
  citations: Citation[];
  onSource: (revision: string, span: string) => void;
}) {
  return (
    <section className="calculation">
      <div className="section-title">
        <h3>Calculated from the encounter ledger</h3>
        <span className="verified">Server calculation</span>
      </div>
      <p className="muted-text">
        {value.total.start} – {value.total.end} · Included psychotherapy
        encounters
      </p>
      <div className="summary-grid">
        <div className="summary">
          <span>Sessions</span>
          <strong>{value.total.sessions ?? "Unknown"}</strong>
        </div>
        <div className="summary">
          <span>Distinct treatment days</span>
          <strong>{value.total.days ?? "Unknown"}</strong>
        </div>
        <div className="summary">
          <span>Patient treatment time</span>
          <strong>{minutes(value.total.seconds)}</strong>
        </div>
      </div>
      {!value.total.complete && (
        <p className="alert warning">
          Coverage, attendance, or duration is unresolved. A definitive total is
          withheld.
        </p>
      )}
      {value.weeks.length > 0 && (
        <div className="weekly-grid">
          {value.weeks.map((week, index) => (
            <article className="week-card" key={index}>
              <strong>
                {week.start} – {week.end}
              </strong>
              <span>
                {week.days ?? "Unknown"} days · {minutes(week.seconds)}
              </span>
              <span className={`disposition ${week.goal_status}`}>
                {human(week.goal_status)}
              </span>
              <small>
                Goal: {week.minimum_days} days AND {week.minimum_minutes} min
              </small>
              <References
                ids={week.citations}
                citations={citations}
                onSource={onSource}
              />
            </article>
          ))}
        </div>
      )}
      <details className="calculation-details">
        <summary>Show contributions and calculation assumptions</summary>
        {value.contributions.map((row) => (
          <div className="contribution" key={row.encounter_id}>
            <span>
              {row.date} · {row.encounter_id} · {row.modality}
            </span>
            <strong>
              {row.disposition === "excluded"
                ? "Excluded"
                : row.disposition === "uncertain"
                  ? "Uncertain"
                  : minutes(row.seconds)}
            </strong>
            <References
              ids={row.citations}
              citations={citations}
              onSource={onSource}
            />
          </div>
        ))}
        {value.notes.map((note) => (
          <p key={note}>{note}</p>
        ))}
      </details>
    </section>
  );
}
