"use client";

import { useState } from "react";
import type { components } from "@/lib/api-schema";

type Analysis = components["schemas"]["AnalysisOut"];

export function EvidenceLedgerView({
  run,
  onSource,
}: {
  run: Analysis;
  onSource: (revision: string, span: string) => void;
}) {
  const [query, setQuery] = useState("");
  const ledger = run.result?.evidence_ledger;
  if (!ledger) return null;
  const matches = (predicate: string, raw: string) =>
    `${predicate} ${raw}`.toLowerCase().includes(query.toLowerCase());
  return (
    <div className="simple-ledger">
      <p className="muted-text">
        {ledger.extractions.length} documents ·{" "}
        {ledger.extractions.reduce((n, d) => n + d.claims.length, 0)} source
        claims
      </p>
      <p className="draft-notice">
        These are source statements. They are not a confirmed clinical summary.
      </p>
      {ledger.limitations.map((item) => (
        <p className="alert warning" key={item}>
          {item}
        </p>
      ))}
      <label className="ledger-search">
        Find a claim
        <input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder="Search claims"
        />
      </label>
      {ledger.extractions.map((document) => {
        const claims = document.claims.filter((claim) =>
          matches(claim.predicate, claim.value.raw),
        );
        if (!claims.length) return null;
        return (
          <section
            className="simple-document"
            key={document.document_version_id}
          >
            <h3>{document.document_id}</h3>
            {claims.map((claim) => {
              const evidence = document.evidence.find((item) =>
                claim.evidence_ids.includes(item.evidence_id),
              );
              return (
                <article className="simple-claim" key={claim.claim_id}>
                  <strong>{claim.predicate}</strong>
                  <p>{claim.value.raw}</p>
                  <small>
                    {claim.polarity} · {claim.epistemic_qualification}
                  </small>
                  {evidence && (
                    <>
                      <blockquote>{evidence.quote}</blockquote>
                      <button
                        className="text-action"
                        onClick={() =>
                          onSource(
                            document.document_version_id,
                            evidence.locator.block_id,
                          )
                        }
                      >
                        Open source
                      </button>
                    </>
                  )}
                </article>
              );
            })}
          </section>
        );
      })}
    </div>
  );
}
