"use client";

import { useEffect, useState } from "react";
import { api } from "@/lib/api";
import type { components } from "@/lib/api-schema";
import { References } from "./evidence-views";

type Analysis = components["schemas"]["AnalysisOut"];
type Source = components["schemas"]["SourceOut"];

export function ReadableAbstractionView({
  run,
  onSource,
}: {
  run: Analysis;
  onSource: (revision: string, span: string) => void;
}) {
  const state = run.result?.readable_abstraction;
  const [selected, setSelected] = useState("");
  const [query, setQuery] = useState("");
  const [showSource, setShowSource] = useState(true);
  const [source, setSource] = useState<Source | null>(null);
  const [sourceError, setSourceError] = useState("");
  const current =
    state?.documents.find((d) => d.profile.revision_id === selected) ??
    state?.documents[0];
  const revision = current?.profile.revision_id;
  useEffect(() => {
    let cancelled = false;
    setSource(null);
    setSourceError("");
    if (revision && showSource) {
      api<Source>(`/source-revisions/${revision}`)
        .then((value) => {
          if (!cancelled) setSource(value);
        })
        .catch(() => {
          if (!cancelled)
            setSourceError("Unable to load the original document.");
        });
    }
    return () => {
      cancelled = true;
    };
  }, [revision, showSource]);
  if (!state || !current) return null;
  const citations = run.result?.citations ?? [];
  const cite = (ids: string[]) => (
    <References ids={ids} citations={citations} onSource={onSource} />
  );
  const profile = current.profile;
  const review = state.reviews?.find((r) => r.target_ref === revision);
  const comparisonReview = state.reviews?.find(
    (r) => r.target_ref === "synthesis",
  );
  const matching = (text: string) =>
    text.toLowerCase().includes(query.toLowerCase());
  return (
    <div className="readable-abstraction">
      {state.limitations.length > 0 && (
        <div className="alert warning">
          <strong>Incomplete abstraction</strong>
          <p>
            Some documents or comparisons need attention. Answers must preserve
            these gaps.
          </p>
          <details>
            <summary>Show details ({state.limitations.length})</summary>
            {state.limitations.map((text, i) => (
              <p key={i}>{text}</p>
            ))}
          </details>
        </div>
      )}
      {state.synthesis && (
        <details className="readable-overview" open>
          <summary>Across the documents</summary>
          <p className="muted-text">
            {comparisonReview?.status === "checked"
              ? "Compared with source evidence. Conflicts and source accounts remain preserved."
              : "Draft comparison — evidence review is incomplete or found issues."}
          </p>
          {state.synthesis.overview.map((fact, i) => (
            <article key={i}>
              <p>{fact.text}</p>
              {cite(fact.citations)}
            </article>
          ))}
          <details>
            <summary>
              Related records and differences (
              {state.synthesis.connections.length})
            </summary>
            <p className="muted-text">
              Evidence-based comparisons. Each source account remains preserved.
            </p>
            {state.synthesis.connections.map((connection, i) => (
              <article key={i}>
                <strong>{connection.kind.replaceAll("_", " ")}</strong>
                <span className="muted-text">
                  {" "}
                  ·{" "}
                  {state.decisions
                    ?.find((d) => d.proposal_path === `/connections/${i}`)
                    ?.status.replaceAll("_", " ") ?? "proposal"}
                </span>
                <p>{connection.text}</p>
                {cite(connection.citations)}
              </article>
            ))}
          </details>
        </details>
      )}
      <div className="readable-controls">
        <label>
          Document ({state.documents.length})
          <select
            value={profile.revision_id}
            onChange={(event) => {
              setSelected(event.target.value);
              setQuery("");
            }}
          >
            {state.documents.map((doc) => (
              <option
                key={doc.profile.revision_id}
                value={doc.profile.revision_id}
              >
                {doc.profile.title} ·{" "}
                {
                  run.result?.document_sources?.find(
                    (s) => s.revision_id === doc.profile.revision_id,
                  )?.filename
                }
              </option>
            ))}
          </select>
        </label>
        <label>
          Find in this abstraction
          <input
            placeholder="Search clinical details"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        </label>
        <label className="readable-toggle">
          <input
            type="checkbox"
            checked={showSource}
            onChange={(e) => setShowSource(e.target.checked)}
          />{" "}
          Original beside abstraction
        </label>
      </div>
      <div className={`readable-comparison ${showSource ? "with-source" : ""}`}>
        {showSource && (
          <section className="readable-original">
            <h3>Original document</h3>
            <pre>{sourceError || source?.text || "Loading original…"}</pre>
          </section>
        )}
        <section className="readable-document">
          <h3>{profile.title}</h3>
          <p className="muted-text">
            {review?.status === "checked"
              ? "Source check completed — no issues flagged."
              : review
                ? "Needs source review"
                : "Source verification not run for this version"}
          </p>
          {review?.report?.issues.map((issue, i) => (
            <article className="alert warning" key={i}>
              <p>{issue.detail}</p>
              {cite(issue.citations)}
            </article>
          ))}
          {review?.error && (
            <p className="alert warning">
              The source check could not finish. Retry this abstraction to check
              it.
            </p>
          )}
          <p className="muted-text">
            {profile.document_type.replaceAll("_", " ")}
            {profile.stated_status ? ` · ${profile.stated_status}` : ""}
          </p>
          {profile.contributors.length > 0 && (
            <p>
              {profile.contributors
                .map((c) => `${c.name} (${c.scope})`)
                .join("; ")}
            </p>
          )}
          {profile.signatures.map((s, i) => (
            <p key={i}>
              <strong>{s.kind}:</strong> {s.name} ·{" "}
              {s.when
                ? `${s.when.date}${s.when.time ? ` ${s.when.time}` : ""}`
                : "Date not stated"}{" "}
              · {s.scope}
            </p>
          ))}
          {current.sections.map((section, i) => {
            const facts = section.facts.filter((f) =>
              matching(`${section.heading} ${f.text}`),
            );
            return facts.length ? (
              <section key={i}>
                <h4>{section.heading}</h4>
                {facts.map((fact, j) => (
                  <article key={j}>
                    <p>{fact.text}</p>
                    {cite(fact.citations)}
                  </article>
                ))}
              </section>
            ) : null;
          })}
          {current.contacts.length > 0 && (
            <details>
              <summary>Contact times and participation</summary>
              {current.contacts.map((contact, i) => (
                <article key={i}>
                  <h4>
                    {contact.service_date ?? "Date unstated"} ·{" "}
                    {contact.service}
                  </h4>
                  <p>
                    {contact.encounter_id} · {contact.attendance}
                  </p>
                  <p>{contact.participants}</p>
                  {contact.intervals.map((interval, j) => (
                    <div key={j}>
                      <p>
                        <strong>
                          {interval.purpose.replaceAll("_", " ")}:
                        </strong>{" "}
                        {interval.start ?? "Start unknown"} –{" "}
                        {interval.end ?? "End unknown"}
                        {interval.documented_minutes !== null
                          ? ` · ${interval.documented_minutes} documented minutes`
                          : ""}
                        . {interval.participants}. {interval.qualification}
                      </p>
                      {cite(interval.citations)}
                    </div>
                  ))}
                </article>
              ))}
            </details>
          )}
          {current.assessments.length > 0 && (
            <details>
              <summary>Assessment values</summary>
              {current.assessments.map((a, i) => (
                <article key={i}>
                  <p>
                    <strong>
                      {a.instrument}
                      {a.item ? ` · ${a.item}` : ""}:
                    </strong>{" "}
                    {a.score ?? "Score unstated"} ·{" "}
                    {a.completed_on ?? "Completion date unstated"}
                  </p>
                  <p>{a.context}</p>
                  {cite(a.citations)}
                </article>
              ))}
            </details>
          )}
          {profile.dates.length > 0 && (
            <details>
              <summary>Document and event dates</summary>
              {profile.dates.map((d, i) => (
                <article key={i}>
                  <p>
                    {d.when.date} {d.when.time} · {d.kind} · {d.scope}
                  </p>
                  {cite(d.citations)}
                </article>
              ))}
            </details>
          )}
        </section>
      </div>
    </div>
  );
}
